def transform(grid):
    """Vertically align every color's shape to the top of the color-8 shape."""
    h = len(grid)
    w = len(grid[0]) if h else 0
    out = [[0] * w for _ in range(h)]
    colors = {v for row in grid for v in row if v != 0}
    anchor_top = min(r for r in range(h) for c in range(w) if grid[r][c] == 8)
    for color in colors:
        cells = [(r, c) for r in range(h) for c in range(w) if grid[r][c] == color]
        top = min(r for r, _ in cells)
        for r, c in cells:
            out[anchor_top + r - top][c] = color
    return out
